/** 
 * Joins this chat room so that the user would start receiving events and messages for it. The method uses the nickname of the local user and the specified password in order to enter the chatroom.
 * @param password the password to use when authenticating on the chatroom.
 * @throws OperationFailedException with the corresponding code if an erroroccurs while joining the room.
 */
public void join(final byte[] password) throws OperationFailedException {
  final IrcConnection connection=this.parentProvider.getIrcStack().getConnection();
  if (connection == null) {
    throw new OperationFailedException("We are currently not connected to the server.",OperationFailedException.NETWORK_FAILURE);
  }
  if (connection.getChannelManager().isJoined(this)) {
    throw new OperationFailedException("Channel is already joined.",OperationFailedException.SUBSCRIPTION_ALREADY_EXISTS);
  }
  try {
    connection.getChannelManager().join(this,password.toString());
  }
 catch (final IllegalArgumentException | NullPointerException | ClassCastException | UnsupportedOperationException | IndexOutOfBoundsException e) {
    throw new OperationFailedException(e.getMessage(),OperationFailedException.CHAT_ROOM_NOT_JOINED,e);
  }
}
